// javascript

function inna_and_pink_pony(n_int, m_int, i_int, j_int, a_int, b_int) {
    const corner_1 = [1, 1];
    const corner_2 = [1, m_int];
    const corner_3 = [n_int, 1];
    const corner_4 = [n_int, m_int];
    const corners = [corner_1, corner_2, corner_3, corner_4];
    let c = Math.max(n_int, m_int);

    for (const each of corners) {
        if (Math.abs(each[0] - i_int) % a_int !== 0 || Math.abs(each[1] - j_int) % b_int !== 0) {
            continue;
        }
        const horizontal_moves = Math.floor(Math.abs(each[0] - i_int) / a_int);
        const vertical_moves = Math.floor(Math.abs(each[1] - j_int) / b_int);
        if (horizontal_moves % 2 !== vertical_moves % 2) {
            continue;
        }
        const each_move = Math.max(horizontal_moves, vertical_moves);
        if ((a_int > Math.max(i_int - 1, n_int - i_int) && Math.abs(each[1] - j_int) > 0) ||
            (b_int > Math.max(j_int - 1, m_int - j_int) && Math.abs(each[0] - i_int) > 0)) {
            break;
        }
        c = Math.min(c, each_move);
    }

    if (c < Math.max(n_int, m_int)) {
        return c.toString();
    } else {
        return "Poor Inna and pony!";
    }
}

